entries[242395] = { ["name"] = "Trockener Mund", ["text"] = "45 Meter Reichweite\nSofort\nFügt allen Zielen in einem kegelförmigen Bereich vor dem Zaubernden 6 Sek. lang alle 5.2 Sek. Feuerschaden zu." }
entries[242396] = { ["name"] = "Nova", ["text"] = "Unbegrenzte Reichweite\nWirken in 2.5 sek.\nErzeugt eine Nova, die Gegnern innerhalb von 12 Metern hohen Feuerschaden sowie 4 Sek. lang alle 1 Sek. zusätzlichen Feuerschaden zufügt." }
entries[242397] = { ["name"] = "Leerenerschöpfung", ["text"] = "Wirken in 2.5 sek. 1 sek. Abklingzeit\nFügt allen Gegnern in der Nähe 10 Sek. lang Schattenschaden zu." }
